        DB::transaction(function () use ($questions, $team): void {
            Team::query()->lockForUpdate()->findOrFail($team->id);
            $existingPrompts = PublishedQuestionVersion::query()
                ->whereHas('question', fn ($query) => $query->where('team_id', $team->id))
                ->pluck('content')
                ->map(fn (array $content): string => QuestionContent::label($content['prompt'] ?? null))
                ->flip();

            $bands = [
                ...array_map(fn (array $question): array => [6, ...$question], $questions),
                ...array_map(fn (array $question): array => [1, ...$question], $this->earlyQuestions()),
            ];

            foreach ($bands as [$age, $difficulty, $prompt, $correct, $one, $two, $three, $explanation]) {
                if ($existingPrompts->has($prompt)) {
                    continue;
                }

                $content = [
                    'prompt' => $prompt,
                    'correct_answer' => $correct,
                    'distractor_one' => $one,
                    'distractor_two' => $two,
                    'distractor_three' => $three,
                    'explanation' => $explanation,
                ];

                $question = Question::query()->create([
                    'team_id' => $team->id,
                    'content' => $content,
                    'difficulty' => $difficulty,
                    'target_age' => $age,
                    'subjects' => ['ידע כללי'],
                    'quiz_eligible' => true,
                ]);

                $question->versions()->create([
                    'locale' => CatalogLocale::BASE,
                    'content' => $content,
                    'difficulty' => $difficulty,
                    'target_age' => $age,
                    'subjects' => ['ידע כללי'],
                    'quiz_eligible' => true,
                ]);
            }
        });
