            [7, 'מה קורה לגובה של מגדל קוביות כשמוסיפים קובייה למעלה?', 'הוא גדל', 'הוא מתקצר', 'הוא נעשה אפס', 'הוא תמיד נשאר זהה', 'הקובייה הנוספת מגדילה את גובה המגדל.'],
            [8, 'מה מאפשר למצנח להאט את הנפילה?', 'התנגדות האוויר', 'משיכת הירח', 'אור חזק', 'צליל חזק', 'האוויר מפעיל כוח על המצנח הפרוש.'],
            [8, 'איך מחלקים ארבע פרוסות לשני ילדים באופן שווה?', 'שתי פרוסות לכל ילד', 'שלוש לאחד ואחת לשני', 'ארבע לכל ילד', 'אחת לכל ילד', 'ארבע מחולק לשתיים שווה שתיים.'],
            [9, 'בצלחת היו שני תותים. הוסיפו שלושה ואכלו אחד. כמה נשארו?', 'ארבעה', 'שניים', 'חמישה', 'שישה', 'שניים ועוד שלושה הם חמישה, ואחרי שאוכלים אחד נשארים ארבעה.'],
            [9, 'מה כדאי לעשות כדי לבדוק איזה משני זרעים גדל מהר יותר?', 'למדוד את שניהם מדי יום', 'לצבוע את העלים', 'לספור את האבנים בגינה', 'להחליף עציצים בכל שעה', 'מדידות חוזרות מראות כמה כל צמח גדל עם הזמן.'],
            [10, 'שלוש כוסות עומדות בשורה. הופכים רק את האמצעית. כמה עדיין עומדות ישר?', 'שתיים', 'אחת', 'שלוש', 'אפס', 'שתי הכוסות שבקצוות לא התהפכו.'],
            [10, 'מה יקרה לנדנדה מאוזנת אם ילד אחד ירד ממנה?', 'הצד של הילד שנשאר ירד', 'שני הצדדים יעלו', 'הנדנדה תתקצר', 'שני הצדדים ייעלמו', 'כשהמשקל נשאר בצד אחד, הצד הזה יורד.'],
            [10, 'מדוע סירה עם חור בתחתית עלולה לשקוע?', 'מים נכנסים ומכבידים עליה', 'האור נעלם', 'הרוח מחליפה צבע', 'המים הופכים לאוויר', 'מים שחודרים לסירה מוסיפים לה משקל.'],
            [10, 'מה משותף לקוביית קרח ולמים בכוס אחרי שהקרח נמס?', 'שניהם מים', 'שניהם מוצקים', 'שניהם אבנים', 'שניהם רותחים', 'המסה משנה את מצב הצבירה של המים.'],
        ];
    }
}
